WITH scoped AS (
    SELECT f.ENTITY_ID, f.ENTITY_NAME, f.AMOUNT_CENTS, f.EVENT_DATE
    FROM ANALYTICS.FACTS f
    WHERE f.TENANT_ID = {{tenant_id}}
        AND f.EVENT_DATE BETWEEN {{start_date}} AND {{end_date}}
),
by_entity AS (
    SELECT
        s.ENTITY_NAME,
        TO_VARCHAR(MAX(s.ENTITY_ID)) AS ENTITY_ID,
        COUNT(*) AS RECORDS,
        SUM(s.AMOUNT_CENTS) AS AMOUNT_CENTS
    FROM scoped s
    GROUP BY s.ENTITY_NAME
),
totals AS (
    SELECT
        COUNT(*) AS TOTAL_ROWS,
        COUNT(*) AS TOTAL_ENTITIES,
        COALESCE(SUM(RECORDS), 0) AS TOTAL_RECORDS,
        COALESCE(SUM(AMOUNT_CENTS), 0) AS TOTAL_AMOUNT,
        TO_VARCHAR((SELECT MIN(s2.EVENT_DATE) FROM scoped s2), 'YYYY-MM-DD') AS FIRST_DATE
    FROM by_entity
)
SELECT
    CURRENT_DATE() AS REPORTED_DATE,
    g.ENTITY_NAME,
    g.ENTITY_ID,
    g.RECORDS,
    g.AMOUNT_CENTS,
    t.TOTAL_ROWS,
    t.TOTAL_ENTITIES,
    t.TOTAL_RECORDS,
    t.TOTAL_AMOUNT,
    t.FIRST_DATE
FROM by_entity g
CROSS JOIN totals t
ORDER BY g.AMOUNT_CENTS DESC, g.ENTITY_NAME
LIMIT 500
